typedef unsigned long long uint64;
typedef float rational_t;

class pstring
{
private:
  uint64 pchunk[4];
  void pack_string(const char *the_string);

public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator == (const pstring &check_me) const
  {
    for (unsigned i = 0; i < 4; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

#define IFC_INTERNAL_GET_MACRO(a,b) { static pstring pstring_get(a); if(att == pstring_get) { val = b; return(true); } }

class ai_locomotion
{
  char data_before_patrol_radius[112];
  rational_t patrol_radius;
  char data_before_jockey_speed[164];
  rational_t jockey_speed;

public:
  bool get_num(const pstring &att, rational_t &val);
};

bool ai_locomotion::get_num(const pstring &att, rational_t &val)
{
  IFC_INTERNAL_GET_MACRO("PATROL_RADIUS", patrol_radius);
  IFC_INTERNAL_GET_MACRO("JOCKEY_SPEED", jockey_speed);

  return(false);
}
